module div_8bit(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, input res_ready, output reg res_valid, output reg [15:0] result
);
// Your implementation goes here
integer i;
reg [7:0] temp_dividend, temp_divisor;
reg [17:0] SR;
reg [16:0] NEG_DIVISOR;
reg [3:0] cnt;
reg start_cnt;
always @(posedge clk or posedge rst) begin
    if(rst) begin
        res_valid <= 1'b0;
        result <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        SR <= 18'b0;
        NEG_DIVISOR <= 17'b0;
        temp_dividend <= 8'b0;
        temp_divisor <= 8'b0;
    end
    else if(opn_valid && !res_valid) begin
        res_valid <= 1'b0;
        result <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b1;
        SR <= {{9{sign&dividend[7]}},dividend,{8{1'b0}}};
        NEG_DIVISOR <= {{8{sign&divisor[7]}},~divisor+1'b1};
        temp_dividend <= dividend;
        temp_divisor <= divisor;
    end
    else if(start_cnt) begin
        if(cnt[3]) begin
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            SR <= {NEG_DIVISOR[16:0]+SR[16:0],SR[8]};
            result <= {SR[17:9],SR[8:1]};
            res_valid <= 1'b1;
        end
        else begin
            cnt <= cnt + 4'b1;
            if(SR[16:0]+NEG_DIVISOR[16:0]<17'd1) begin
                SR <= {SR[17:0],1'b0};
            end
            else begin
                SR <= {NEG_DIVISOR[16:0]+SR[16:0],SR[8]};
            end
        end
    end
    else if(res_valid && res_ready) begin
        res_valid <= 1'b0;
    end
    else begin
        res_valid <= res_valid;
    end
end
endmodule
